  /**
   * The physical or logical bearer carrying this link, e.g. 'UHF/VHF AM voice radio', 'wired aircraft intercom', 'SATCOM datalink', 'tactical mesh radio (MANET)', 'DoD web network (HTTPS)', 'in-person'.
   */
